create function jugar_mini(p_partida int, p_cliente int, yo text, preguntas text[]) returns partidas
language plpgsql as $$
declare p partidas%rowtype; q text;
begin
  select * into p from partidas where id = p_partida for update;                  -- bloquea la fila de la partida
  if exists (select 1 from jugadas where cliente_id = p_cliente) then return p; end if;   -- reintento: ya estaba guardado
  if p.turno_de is distinct from yo then raise exception 'no_es_tu_turno'; end if;
  foreach q in array preguntas loop
    insert into jugadas values (p_cliente * 100 + array_position(preguntas, q), p_partida, yo, q);
  end loop;
  insert into jugadas values (p_cliente, p_partida, yo, '__turno__');
  update partidas set turno_de = 'beto', ronda = ronda + 1 where id = p_partida returning * into p;
  insert into avisos (usuario, cuerpo) values ('beto', 'Te toca jugar');
  return p;
end $$;
